/* Bigorna Rooms: the Simplified Chinese of the interface, read by tr() (idioma.js), in the same shape as idioma_pt.js.
   exact: English text -> Simplified Chinese. {n} stands for a number and “{q}” / "{q}" for a quoted name (kept as it is);
   {Q} is that quoted text translated too. patterns: [RegExp, replacement]: $1 is kept as it is, $T1 is translated.
   Game terms follow the Simplified Chinese translation of the game where it exists (Descent). No text of the game is copied here. */
