    "Put the copy on a tile of this room at level {n}.": "把副本放在此房间层级 {n} 的板块上。",
    "Copied with its texts, triggers and requirements. An “{q}” trigger is not copied: two objects may open the same room, but add that trigger by hand.": "已连同文本、触发器和要求一起复制。“{Q}”触发器不会被复制：两个物件可以打开同一个房间，但请手动添加该触发器。",
    "Tile {n} is already in this room.": "板块 {n} 已经在此房间中。",
    "Put it on a tile of this room at level {n} (the ribbon level).": "把它放在此房间层级 {n}（功能区当前层级）的板块上。",
    "At that level the tile overlaps another one.": "在该层级上，此板块会与另一个板块重叠。",
