    "Tiers {n}, {n} and {n} for {n}–{n}, {n} and {n} heroes (room intensity {n}, progression {n}, points shared by {n} monsters).": "等阶 {n}、{n} 和 {n}，分别对应 {n}–{n}、{n} 和 {n} 位英雄（房间强度 {n}，进度 {n}，点数由 {n} 个怪物分摊）。",
    "There is no other room yet.": "还没有其他房间。",
    "Move the tile (and what sits on it) to which room?": "把板块（以及上面的东西）移到哪个房间？",
    "Hero spaces only exist in the starting room: they were dropped.": "英雄格只存在于起始房间：它们已被丢弃。",
    "Room {n} becomes the starting room: give it hero spaces.": "房间 {n} 成为起始房间：请为它设置英雄格。",
    "Music added.": "音乐已添加。",
    "Music added (a large file: an OGG of {n} to {n} MB is plenty).": "音乐已添加（文件较大：{n} 到 {n} MB 的 OGG 就足够了）。",
