    "Starting inventory": "起始持有物",
    "Your first interaction": "你的第一个互动",
    "Every map starts with the starting room. Create it with the button on the left.": "每张地图都从起始房间开始。用左边的按钮创建它。",
    "Pick a tile in the palette and put it on the board; press R to rotate it. For now, place two different tiles: they will be taken out of the box and set up during the game.": "在调色板中选择一个板块并把它放到版图上；按 R 旋转。现在请放置两个不同的板块：游戏中会把它们从盒子里取出并摆放好。",
    "The Hero button (H) sets the starting squares of our adventurers. Select 2 to 4 squares in the starting room.": "“英雄”按钮（H）用于设置冒险者的起始方格。在起始房间中选择 2 到 4 个方格。",
    "To reveal the map little by little, we need to create a new room. It appears when an object is used, by programming a trigger that opens a room. Let us try it: click the Object button (O) and pick a door. Then add an “Open a room” trigger.": "要逐步揭示地图，我们需要创建一个新房间。它会在某个物件被使用时出现，方法是编写一个打开房间的触发器。来试试吧：点击“物件”按钮（O）并选择一扇门。然后添加一个“打开房间”触发器。",
    "You have created your first interaction with the scenery. In the game, the hero will open the door and release the tiles of the next room. Now, let us fill that room: put a chest in a room and program a trigger that gives items to the players (the other buttons and triggers wait for this).": "你已经创建了与场景的第一个互动。在游戏中，英雄会打开这扇门，放出下一个房间的板块。现在来填充这个房间：在房间里放一个宝箱，并编写一个给玩家物品的触发器（其他按钮和触发器稍后再说）。",
    "📂 Import a save of the game (.sav)": "📂 导入游戏存档（.sav）",
    "Clear all": "全部清除",
    "Search an item…": "搜索物品……",
    "Only what the party has": "仅限小队拥有的",
    "skills": "技能",
    "Others": "其他",
    "Clear the whole starting inventory?": "清空全部起始持有物？",
    "Replace the starting inventory with the one of this save?": "用此存档中的持有物替换起始持有物？",
    "Imported from the save": "从存档导入",
    "This file is not a save of the game.": "这个文件不是游戏存档。",
    "For a party of veterans: what it already holds when the campaign starts, won in earlier battles. The party receives it when the campaign begins. Items come from the Workshop (Items and Weapons tabs), the skills from the Skills tab (or the game’s). The item pools of the generated maps leave out the unique items the party already has, and the game never gives an item twice.": "适用于老练的小队：战役开始时已经拥有的东西，是之前战斗中赢得的。小队会在战役开始时获得这些。物品来自工坊（“物品”和“武器”标签页），技能来自“技能”标签页（或游戏中的技能）。生成地图的物品池会排除小队已拥有的独特物品，游戏也绝不会重复给予同一件物品。",
    "Starting gold": "起始金币",
    "The Workshop has no items yet: import them in the Items tab.": "工坊还没有物品：请在“物品”标签页中导入。",
    "Skills (unlocked)": "技能（已解锁）",
    "+ add a skill…": "+ 添加技能……",
