    "Forged: the three pieces now have their own pictures, laid out as you assembled them.": "已锻造：三个部件现在都有了自己的图片，按你组装的方式排列。",
    "Forged: the three pieces now have their own pictures, laid out as you assembled them; {n} fixed box(es).": "已锻造：三个部件现在都有了自己的图片，按你组装的方式排列；{n} 个固定框。",
