    "Downloaded {n} files. Put them all in a folder named “{q}” inside Bigorna\\Mapas.": "已下载 {n} 个文件。把它们全部放进 Bigorna\\Mapas 中名为“{Q}”的文件夹。",
    "Recalculate tier {n} from tier {n} with the game’s curve? Their current numbers are replaced.": "用游戏的曲线根据等阶 {n2} 重新计算等阶 {n1}？其当前数值将被替换。",
    "Recalculate tiers {n}–{n} from tier {n} with the game’s curve? Their current numbers are replaced.": "用游戏的曲线根据等阶 {n3} 重新计算等阶 {n1}–{n2}？其当前数值将被替换。",
    "OK: first move all its triggers to another object (you click it), then delete.": "确定：先把它的所有触发器移到另一个物件上（由你点击选择），然后再删除。",
    "Cancel: delete anyway; the room stays without an opener until another object gets an “{q}” trigger.": "取消：仍然删除；在另一个物件获得“{Q}”触发器之前，该房间将没有开启方式。",
    "This is the only trigger that opens room {n}.": "这是唯一能打开房间 {n} 的触发器。",
    "Cancel: delete the trigger; the room stays without an opener until another object gets an “{q}” trigger.": "取消：删除该触发器；在另一个物件获得“{Q}”触发器之前，该房间将没有开启方式。",
    "Removal trigger(s) added to “{q}”. Place the pillar again.": "已向“{Q}”添加移除触发器。请重新放置柱子。",
