    "I know my way around": "我已经很熟悉了",
    "Are you sure about that?": "你确定吗？",
    "The tutorial walks you through the editor step by step. If you ever want to revisit it, you can repeat it from ⚙ Settings.": "教程会一步步带你了解编辑器。如果你想再看一遍，可以在 ⚙ 设置中重新开始。",
    "Yes, skip it": "是的，跳过",
    "Skip the tutorial? Everything unlocks now. If you change your mind, ⚙ Settings can run it again.": "跳过教程？所有内容现在都会解锁。如果你改变主意，可以在 ⚙ 设置中重新运行。",
    "Right here!": "就在这里！",
    "With Hero (H), click the squares where the heroes start: choose 2 to 4 squares in the starting room.": "用“英雄”（H）点击英雄起始的方格：在起始房间中选择 2 到 4 个方格。",
    "Nice work!": "干得好！",
    "The first room is already tied to its door: when a hero opens it, the next room appears on the table. Now let’s add a chest and make it hand out some items to the party. The other buttons and triggers can wait their turn.": "第一个房间已经与它的门绑定：当英雄打开门时，下一个房间就会出现在桌面上。现在我们来添加一个宝箱，让它给小队一些物品。其他按钮和触发器可以稍后再说。",
    "Place a Chest (Object) in a room, select it and add the “Give or take away an item” trigger. Choose what it gives the party when it is opened.": "在房间里放一个宝箱（物件），选中它并添加“给予或拿走物品”触发器。选择打开时给予小队的东西。",
    "A brand-new room": "全新的房间",
    "The door came with its script and has already created a new room tied to it. Lay out its tiles whenever you like. Now for some monsters: the Enemy button is unlocked.": "这扇门带有它的脚本，已经创建了一个与它绑定的新房间。你可以随时铺设它的板块。现在来点怪物吧：“敌人”按钮已解锁。",
    "Let’s put some monsters in a room: press Enemy (E).": "我们在房间里放些怪物吧：按“敌人”（E）。",
    "Ops!": "哎呀！",
    "In the Workshop, press “Import…” and bring in about 10 monsters from the game for this map.": "在工坊中按“导入……”，为这张地图从游戏中带入大约 10 个怪物。",
    "Have a look around the other workshops if you like, then head back to Rooms (◂ Rooms).": "如果你愿意，可以看看其他工坊，然后回到房间（◂ 房间）。",
    "Now for the room generator. Press ✦ Generate room and click the door that will connect to the new room.": "现在来试试房间生成器。按“✦ 生成房间”，然后点击将连接新房间的门。",
    "First move the room (drag it or use the arrows) or turn it (R). “Use this” becomes available as soon as the room has moved.": "先移动房间（拖动或使用方向键）或旋转它（R）。房间一移动，“使用这个”就可以使用了。",
    "You have built rooms by hand, programmed objects, brought in monsters, and generated a room. Now only the campaign remains: it connects maps on the world map, with scenes, choices, and rewards between them. Press “Start a campaign” and the rest of the editor opens up.": "你已经手动建造了房间、为物件编程、带入了怪物，还生成了一个房间。现在只剩下战役了：它在世界地图上连接各张地图，地图之间有场景、选择和奖励。按“开始战役”，编辑器的其余部分就会开放。",
    "Press “Start a campaign”: everything is unlocked from there.": "按“开始战役”：从那里开始，所有内容都会解锁。",
    "Explore the story flow, a scene (and its boxes), the starting inventory, and the story variables. Then go back to Rooms (◂ Rooms) to finish.": "探索剧情流程、一个场景（及其对话框）、起始持有物和剧情变量。然后回到房间（◂ 房间）完成教程。",
    "Open the Workshop": "打开工坊",
    "Other finer conditions of this feat in the game (first attack of the round, other heroes…) are kept as they are.": "游戏中此功绩的其他更细的条件（本轮第一次攻击、其他英雄……）保持不变。",
    "Otherwise the scene is skipped (the story goes on).": "否则跳过该场景（剧情继续）。",
    "Pick a box on the left, or add one.": "在左侧选择一个对话框，或添加一个。",
    "Pick a feat on the left, import one from the game, or write a new one.": "在左侧选择一个功绩，从游戏导入一个，或写一个新的。",
    "Pick a kind on the left.": "在左侧选择一个种类。",
    "Pick a recipe on the left, import one from the game, or write a new one.": "在左侧选择一个配方，从游戏导入一个，或写一个新的。",
    "Pick another object": "选择另一个物件",
    "Pillars go in the sockets of an elevated tile of this room at level {n} (the dots on its edges).": "柱子放在此房间层级 {n} 某个高架板块的插槽中（板块边缘的圆点）。",
    "Pillars hold up elevated tiles: pick the level of that tile ({n} to {n}) on the ribbon first.": "柱子支撑高架板块：请先在功能区选择该板块的层级（{n} 到 {n}）。",
    "Place the city…": "放置城市……",
