    "The game's mist over it": "上方有游戏中的雾",
    "The monster lunges forward, roaring…": "怪物咆哮着向前猛扑……",
    "The platform is a box standing on the floor: it needs no pillars.": "平台是立在地面上的箱子：它不需要柱子。",
    "The rune: damage, damage types and power": "符文：伤害、伤害类型和威能",
    "First effect: an ability that may trigger on hits": "第一个效果：命中时可能触发的能力",
    "Second effect: another ability that may trigger on hits": "第二个效果：命中时可能触发的另一个能力",
    "The spaces work together, by the game's rule for random spawns: one budget of points for all of them (intensity ÷ {n} × heroes × {n} × progression, Map setup › Balancing) decides how many monsters enter and how strong. All may enter, or just one strong monster.": "这些格子按照游戏的随机生成规则共同运作：所有格子共用一份点数预算（强度 ÷ {n} × 英雄数 × {n} × 进度，地图设置 › 平衡），决定进入多少怪物以及它们有多强。可能全部进入，也可能只进入一个强大的怪物。",
    "The workshop has no items yet.": "工坊还没有物品。",
    "The workshop has no items yet: create or import them in the Items tab.": "工坊还没有物品：请在“物品”标签页中创建或导入。",
    "The workshop has no items: import or create them in the Items tab.": "工坊没有物品：请在“物品”标签页中导入或创建。",
