    "This file was not made with Bigorna Rooms (it has no room data), so its logic cannot be read.": "此文件不是用 Bigorna Rooms 制作的（没有房间数据），因此无法读取它的逻辑。",
    "This objective is the mission of the map: completing it ends the map.": "此任务目标是地图的任务：完成它即结束地图。",
