    "Use the standing card picture": "使用立牌图片",
    "Used again, the object starts the count over.": "再次使用时，物件会重新开始计数。",
    "Used, it leaves the board (like a point of interest in the game).": "使用后，它会离开版图（像游戏中的兴趣点一样）。",
    "Using this object counts as an objective of the room (listed and ticked). Older maps only: use “{q}”.": "使用此物件算作房间的一个任务目标（列出并勾选）。仅限旧地图：请使用“{Q}”。",
