    "Which monsters count": "哪些怪物计入",
    "Which one?": "哪一个？",
    "Workshop objects (made in the Workshop)": "工坊物件（在工坊中制作）",
    "Workshop tiles (made in the Workshop)": "工坊板块（在工坊中制作）",
    "Worn by a hero: a card with its rule, kept in the party’s inventory.": "由英雄佩戴：一张带有规则的卡牌，保存在小队的持有物中。",
    "Writes the .bmap (download), then clears.": "写出 .bmap（下载），然后清空。",
    "✎ Draw a road": "✎ 绘制道路",
    "✓ Finish this road": "✓ 完成此道路",
    "Tiles can stand at levels 1, 2 and 3 (the level buttons) on": "板块可以放在层级 1、2 和 3（层级按钮）的",
    "; the app counts the pillars your boxes have.": "上；应用会统计你盒中拥有的柱子。",
    "pillars (P)": "柱子（P）",
    "Counts": "计数",
    "keep a number during the map (keys found, seals broken): triggers add to them, and a map objective can wait for the total.": "在地图中保存一个数字（找到的钥匙、破坏的封印）：触发器会增加它们，地图任务目标可以等待总数。",
    "Export map": "导出地图",
    "The": "此",
    "Workshop (⚒)": "工坊（⚒）",
    "Map setup": "地图设置",
    "Start a campaign": "开始战役",
    "Press": "按",
    "3D": "3D",
    "Hero (H)": "英雄（H）",
    "Enemy (E)": "敌人（E）",
    "When the room starts, the game fills these spaces with its own rule for random spawns: points = intensity ÷ {n} × heroes × {n} × progression": "房间开始时，游戏会按照自己的随机生成规则填充这些格子：点数 = 强度 ÷ {n} × 英雄数 × {n} × 进度",
    "When the room opens, the game fills these spaces with its own rule for random spawns: points = intensity ÷ {n} × heroes × {n} × progression": "房间打开时，游戏会按照自己的随机生成规则填充这些格子：点数 = 强度 ÷ {n} × 英雄数 × {n} × 进度",
    "When the room opens, the game fills these spaces with its own rule for random spawns: points = intensity ÷ {n} × heroes × {n} × progression; it takes the highest tier of the map’s range the points pay for (costs {n}, {n}, {n}, {n}, {n}, {n}…), and monsters of the pool that have that tier enter, one per space (up to {n}), while the points last. Leftover points go to the next balanced room. All may enter, or just one strong monster.": "房间打开时，游戏会按照自己的随机生成规则填充这些格子：点数 = 强度 ÷ {n} × 英雄数 × {n} × 进度；它会选取点数足以支付的地图范围内最高等阶（花费 {n}、{n}、{n}、{n}、{n}、{n}……），池中拥有该等阶的怪物会进入，每格一个（最多 {n} 个），直到点数用完。剩余点数转入下一个平衡房间。可能全部进入，也可能只进入一个强大的怪物。",
    "{n} balanced spaces in this room": "此房间有 {n} 个平衡格",
    "{n} monsters, tier {n}": "{n} 个怪物，等阶 {n}",
    "{n} monster, tier {n}": "{n} 个怪物，等阶 {n}",
    "{n} monsters, tier {n} (no more miniatures)": "{n} 个怪物，等阶 {n}（没有更多模型）",
    "none: no free miniature": "无：没有空闲模型",
    "Room {n} · space {n},{n}": "房间 {n} · 格子 {n},{n}",
    "{n} rooms · side quest": "{n} 个房间 · 支线任务",
    "A change applies while this campaign is played, to every copy of the part, also the ones bought or found later.": "更改在游玩此战役期间生效，适用于该部件的每个副本，包括之后购买或找到的。",
    "Pick a kind of weapon, then its heads, hafts or grips. What you change applies while this campaign is played (to every copy of the part, also the ones bought or found later); what you leave stays as in the game.": "选择一种武器，然后选择它的头部、杆或握柄。你更改的内容在游玩此战役期间生效（适用于该部件的每个副本，包括之后购买或找到的）；未更改的保持游戏原样。",
    "Pick a kind of weapon, then its heads, hafts or grips. What you change applies while this campaign is played (to every copy of the part, also the ones bought or found later)": "选择一种武器，然后选择它的头部、杆或握柄。你更改的内容在游玩此战役期间生效（适用于该部件的每个副本，包括之后购买或找到的）",
    "Here you prepare the monsters of this campaign. Only the monsters listed here can be placed on the board or drawn from the spawn pool.": "你在这里准备此战役的怪物。只有这里列出的怪物才能放到版图上或从生成池中抽取。",
    "A short list is easier to balance and to test; add more as the campaign grows.": "短名单更容易平衡和测试；随着战役扩展再添加更多。",
    "add more as the campaign grows.": "随着战役扩展再添加更多。",
    "Here you choose the items of this campaign: import them from the game, change them (name, rarity, value, damage, abilities) or create your own. Only the items listed here can be dropped by monsters, found or given by triggers, and the": "你在这里选择此战役的物品：从游戏中导入、修改（名称、稀有度、价值、伤害、能力）或创建你自己的。只有这里列出的物品才能由怪物掉落、被找到或由触发器给予；而",
    "Strong items early make the fights easy; too few, or weak ones, leave the heroes behind the monsters. Pick them on purpose, thinking of the heroes' progress along the campaign.": "过早出现强力物品会让战斗变得简单；太少或太弱则会让英雄落后于怪物。请有意识地挑选，考虑英雄在整个战役中的成长。",
    "too few, or weak ones, leave the heroes behind the monsters. Pick them on purpose, thinking of the heroes' progress along the campaign.": "太少或太弱则会让英雄落后于怪物。请有意识地挑选，考虑英雄在整个战役中的成长。",
    "Each sheet changes one of the six heroes of the game while this campaign is played: name, portrait and animated figure. Their weapons are in the Weapons tab. What you leave as it is stays as in the game.": "每张表格会在游玩此战役期间更改游戏六位英雄中的一位：名字、肖像和动画模型。他们的武器在“武器”标签页中。未更改的内容保持游戏原样。",
    "The item workshop": "物品工坊",
    "The monster workshop": "怪物工坊",
    "is what random-item triggers draw from.": "是随机物品触发器的抽取来源。",
    "The selection of available items is essential for the balance of the game.": "可用物品的选择对游戏平衡至关重要。",
    "The party has it from the start of the campaign (the heroes pick it in the hero choice)": "小队从战役开始时就拥有它（英雄在选择英雄时挑选）",
