    "the intensity of the rooms with monsters and of the triggers that call monsters from the pool, all by the same step (from −6 to +6, always within 1 to 10);": "有怪物的房间以及从池中召唤怪物的触发器的强度，全部按同一步长调整（从 −6 到 +6，始终在 1 到 10 之间）；",
    "the tiers for 1–2, 3 and 4 heroes of the monsters placed by hand, by the game's rule (as ⚖ Balance on a monster).": "手动放置的怪物在 1–2、3 和 4 位英雄时的等阶，按游戏规则调整（与怪物上的“⚖ 平衡”相同）。",
    "the campaign progression, the monster and item pools, the monsters themselves, the objects, the triggers and the texts.": "战役进度、怪物池和物品池、怪物本身、物件、触发器和文本。",
