    "What the game would do": "游戏会怎么做",
    "When the group is defeated": "该组被击败时",
    "When the room starts, the game fills these spaces with its own rule for random spawns: points = intensity ÷ {n} × heroes × {n} × progression; it takes the highest tier of the map’s range the points pay for (costs {n}, {n}, {n}, {n}, {n}, {n}…), and monsters of the pool that have that tier enter, one per space (up to {n}), while the points last. Leftover points go to the next balanced room. All may enter, or just one strong monster.": "房间开始时，游戏会按照自己的随机生成规则填充这些格子：点数 = 强度 ÷ {n} × 英雄数 × {n} × 进度；它会选取点数足以支付的地图范围内最高等阶（花费 {n}、{n}、{n}、{n}、{n}、{n}……），池中拥有该等阶的怪物会进入，每格一个（最多 {n} 个），直到点数用完。剩余点数转入下一个平衡房间。可能全部进入，也可能只进入一个强大的怪物。",
    "change": "更改",
    "it takes the highest tier of the map’s range the points pay for (costs {n}, {n}, {n}, {n}, {n}, {n}…), and monsters of the pool that have that tier enter, one per space (up to {n}), while the points last. Leftover points go to the next balanced room. All may enter, or just one strong monster.": "它会选取点数足以支付的地图范围内最高等阶（花费 {n}、{n}、{n}、{n}、{n}、{n}……），池中拥有该等阶的怪物会进入，每格一个（最多 {n} 个），直到点数用完。剩余点数转入下一个平衡房间。可能全部进入，也可能只进入一个强大的怪物。",
