    "What happens once, when the count reaches {n} (the total of the counter). Several triggers run in order.": "计数达到 {n}（计数器的总数）时发生一次的事情。多个触发器按顺序运行。",
    "When the balanced group is defeated: “{q}”": "平衡组被击败时：“{Q}”",
    "A goal on this map, announced when the monster is defeated and listed with the objectives. An objective does not end the map: the mission does (Map setup). An objective can be chosen there as the mission.": "这张地图上的一个目标，在怪物被击败时公布，并与任务目标一起列出。任务目标不会结束地图：任务才会（地图设置）。可以在那里选择一个任务目标作为任务。",
    "From when the monster is defeated, the round counter runs the triggers inside: every N rounds (as many times as you say, or to the end of the map), or once, N rounds later. For a wave, put “{q}” inside: the spawn has its own “{q}”.": "从怪物被击败时起，轮数计数器运行其中的触发器：每 N 轮一次（按你设定的次数，或直到地图结束），或在 N 轮后运行一次。要制作一波敌人，把“{Q}”放在里面：生成有自己的“{Q}”。",
