    "You found a": "你找到了一个",
    "You lost a": "你失去了一个",
    "[count] is the name of the counter (highlighted like the rule words of the game), [n] the count after this trigger, [total] the total of the counter (Counts button). Missions and requirements can wait for the counter to reach a number (“{q}”).": "[count] 是计数器的名称（像游戏的规则词一样高亮显示），[n] 是此触发器之后的计数，[total] 是计数器的总数（“计数”按钮）。任务和要求可以等待计数器达到某个数字（“{Q}”）。",
    "count": "计数",
    "of": "/",
