    "total": "总数",
    "As a guide: {n} success is easy, {n} standard, {n} hard, {n} or more extreme.": "参考：需要 {n} 个成功为简单，{n} 个为标准，{n} 个为困难，{n} 个或更多为极难。",
    "If they fail": "如果失败",
