    "Question": "问题",
    "Then": "然后",
    "each answer may show a text afterwards and have its own triggers.": "每个回答之后都可以显示一段文本，并有自己的触发器。",
    "\"{q}\": objective without its object": "“{Q}”：任务目标没有对应物件",
    "A counter reaches a number": "计数器达到某个数字",
    "An object is used (click it)": "使用一个物件（点击它）",
    "An objective does not end the map. To make it the mission, pick it in Map setup → Final mission → “{q}”.": "任务目标不会结束地图。要把它设为任务，请在 地图设置 → 最终任务 → “{Q}”中选择它。",
    "Completed when": "完成条件",
    "Completed when it reaches": "达到以下数值时完成",
    "Declared at the table": "在桌面上宣告",
    "Declared at the table: the app only shows the objective text among the objectives and checks nothing by itself. It counts as completed when the table marks it in the Bigorna panel of the game (F{n} → “{q}”)": "在桌面上宣告：应用只会在任务目标中显示该目标文本，自己不检查任何东西。当玩家在游戏的 Bigorna 面板中标记它时（F{n} → “{Q}”），它才算完成",
    "Declared at the table: the app only shows the objective text among the objectives and checks nothing by itself. It counts as completed when the table marks it in the Bigorna panel of the game (F{n} → “{q}”); only then the requirement “{q}” holds and, if it was chosen as the mission, the map ends.": "在桌面上宣告：应用只会在任务目标中显示该目标文本，自己不检查任何东西。当玩家在游戏的 Bigorna 面板中标记它时（F{n} → “{Q}”），它才算完成；只有这时要求“{Q}”才成立，如果它被选为任务，地图就会结束。",
    "Give each object that counts (each key, each lever) an “{q}” trigger with this counter. The mission ends by itself when the number is reached.": "给每个计入的物件（每把钥匙、每根拉杆）添加一个使用此计数器的“{Q}”触发器。达到该数字时，任务会自动结束。",
    "Monsters are defeated": "击败怪物",
    "Object:": "物件：",
    "Objective text": "任务目标文本",
    "Of the room": "所属房间",
    "What the players must do, as shown in the objectives": "玩家必须做的事，按任务目标中显示",
    "only then the requirement “{q}” holds and, if it was chosen as the mission, the map ends.": "只有这时要求“{Q}”才成立，如果它被选为任务，地图就会结束。",
    "This map is not in a campaign yet.": "这张地图还不在任何战役中。",
