    "A new haft of the workshop for this weapon: an item the party gets from a trigger or crafts with a recipe": "此武器的一个工坊新杆：小队通过触发器获得或用配方制作的物品",
    "A new grip of the workshop for this weapon: an item the party gets from a trigger or crafts with a recipe": "此武器的一个工坊新握柄：小队通过触发器获得或用配方制作的物品",
    "None yet (“{q}” above). A new haft is an item: the party gets it from a “{q}” trigger or crafts it with a recipe, and fits it in the armory.": "还没有（上方的“{Q}”）。新杆是一件物品：小队通过“{Q}”触发器获得或用配方制作，然后在军械库中装配。",
