    "The crafting opens in its own window over the board; the next triggers run when it closes. To charge an entrance or limit who may enter, put a requirement on this trigger.": "制作会在版图上方的独立窗口中打开；关闭后运行接下来的触发器。要收取入场费或限制谁可以进入，请给此触发器加上要求。",
    "“{q}” can now be used every time (change it in “{q}”); the trigger says how many times the crafting opens.": "“{Q}”现在每次都可以使用（可在“{Q}”中修改）；触发器决定制作打开多少次。",
