    "The armory has closed.": "军械库已关闭。",
    "The shop opens in its own window over the board; the next triggers run when it closes. To charge an entrance or limit who may enter, put a requirement on this trigger.": "商店会在版图上方的独立窗口中打开；关闭后运行接下来的触发器。要收取入场费或限制谁可以进入，请给此触发器加上要求。",
    "The armory opens in its own window over the board; the next triggers run when it closes. Heroes whose weapons this map sets (Workshop) keep them.": "军械库会在版图上方的独立窗口中打开；关闭后运行接下来的触发器。此地图设定了武器的英雄（工坊）会保留这些武器。",
    "Stock": "库存",
    "The city’s shop": "城市的商店",
    "My list": "我的列表",
    "The item pool of the map": "地图的物品池",
    "(the campaign’s current stock: what the party buys here leaves the city’s shop, what it sells goes there, as in the game)": "（战役当前的库存：小队在这里购买的东西会离开城市的商店，出售的东西会进入那里，与游戏中一样）",
    "items, consumables, recipes and materials you pick, with how many of each": "你选择的物品、消耗品、配方和材料，以及各自的数量",
