    "Purchases per visit (0 = no limit)": "每次拜访的购买次数（0 = 无限制）",
    "The item pool of the map is empty: add items to it in Map setup.": "地图的物品池是空的：请在地图设置中向其中添加物品。",
    "“{q}” can now be used every time (change it in “{q}”); the trigger says how many times the shop opens.": "“{Q}”现在每次都可以使用（可在“{Q}”中修改）；触发器决定商店打开多少次。",
    "“{q}” can now be used every time (change it in “{q}”); the trigger says how many times the armory opens.": "“{Q}”现在每次都可以使用（可在“{Q}”中修改）；触发器决定军械库打开多少次。",
    "\"{q}\": shop without stock (pick where it comes from)": "“{Q}”：商店没有库存（请选择库存来源）",
    "\"{q}\": shop with an empty list": "“{Q}”：商店的列表是空的",
