    "\"{q}\": shop of the item pool, and the pool is empty (warning)": "“{Q}”：商店使用物品池，但池是空的（警告）",
    "\"{q}\": armory where nothing may change": "“{Q}”：军械库中没有可更换的东西",
    "Trigger <b>Shop / Armory</b>: the party visits a shop or an armory in the middle of the map, as in the city, then goes on: a merchant in the camp, a smith at the outpost.": "触发器 <b>商店 / 军械库</b>：小队在地图中途拜访商店或军械库，就像在城市中一样，然后继续前进：营地里的商人、前哨站的铁匠。",
    "Give": "给予",
    "Random crafting materials": "随机制作材料",
    "Units drawn at random from the materials the party carries (never below zero).": "从小队携带的材料中随机抽取的单位（绝不低于零）。",
    "The party has gold": "小队拥有金币",
    "The party must have at least this much gold (a merchant’s price).": "小队必须至少拥有这么多金币（商人的要价）。",
    "takes {n} gold": "拿走 {n} 金币",
