    "The six profiles of the game (class, weapons, skills and feats) go into the campaign. Each is played by the game’s hero (as in the game) or by a hero of your roster, put in it on the hero’s own sheet.": "游戏的六个档案（职业、武器、技能和功绩）会进入战役。每个档案由游戏中的英雄扮演（与游戏中一样），或由你名册中的英雄扮演，在该英雄自己的表格中设置。",
    "The six profiles of the game (class, weapons, skills and feats) go into the map. Each is played by the game’s hero (as in the game) or by a hero of your roster, put in it on the hero’s own sheet.": "游戏的六个档案（职业、武器、技能和功绩）会进入地图。每个档案由游戏中的英雄扮演（与游戏中一样），或由你名册中的英雄扮演，在该英雄自己的表格中设置。",
