    "(the profile’s)": "（档案的）",
    "Each weapon has one hero in the game (its parts, the shop, the inventory and the feats follow it). Picking the weapon of another hero hands him this one in exchange. The numbers come from the weapons: they are changed in the Weapons tab. The weapons belong to the profile: they stay with it if the hero leaves.": "每件武器在游戏中属于一位英雄（它的部件、商店、持有物和功绩都跟随它）。选择另一位英雄的武器，会把这一件交换给他。数值来自武器：在“武器”标签页中修改。武器属于档案：如果英雄离开，武器仍留在档案中。",
    "The weapons belong to the profile: they stay with it if the hero leaves.": "武器属于档案：如果英雄离开，武器仍留在档案中。",
