    "Drag the pieces to put the weapon together as you want it": "拖动部件，按你想要的方式组装武器",
    "Drag the pieces to put the weapon together as you want it; the wheel (or the slider) changes the size of the chosen piece, Shift+wheel, Q/E or the turn slider rotate it, the arrows nudge it. A piece only shows inside its own box: what goes out of it is cut (shown faint).": "拖动部件，按你想要的方式组装武器；滚轮（或滑块）改变所选部件的大小，Shift+滚轮、Q/E 或旋转滑块可旋转它，方向键可微调。部件只在自己的框内显示：超出框的部分会被裁掉（淡色显示）。",
