    "Potions and one-use cards the heroes spend during a quest. Only items listed in the workshop can be given by triggers, rewards and dialogues, dropped by monsters or crafted.": "英雄在任务中使用的药水和一次性卡牌。只有工坊中列出的物品才能通过触发器、奖励和对话给予，由怪物掉落或被制作。",
