    "Range": "范围",
    "Rarity": "稀有度",
    "Recalculate the other tiers from this one with the game's own curve: health grows ×{n}, ×{n}, ×{n}, ×{n}, ×{n}, ×{n}, ×{n} per tier, defense +{n} per tier, attack +{n} up to tier {n} and then +{n} every two tiers. With this tier alone, it creates the tiers up to {n}": "用游戏自己的曲线根据此等阶重新计算其他等阶：生命值每阶 ×{n}、×{n}、×{n}、×{n}、×{n}、×{n}、×{n}，防御每阶 +{n}，攻击每阶 +{n}（直到等阶 {n}），之后每两阶 +{n}。如果只有此等阶，它会创建直到 {n} 的等阶",
