    "Boxes of “{q}”: drag from a box’s ● (or an answer’s ●) onto another box to say what comes next": "“{Q}”的对话框：从一个对话框的 ●（或回答的 ●）拖到另一个对话框上，指定接下来的内容",
    "Boxes play in the order of the arrows, starting at the first. A question box branches: each answer leads to its own next box. A video box plays your own film (MP{n} or WebM) between the other boxes.": "对话框按箭头顺序播放，从第一个开始。问题对话框会产生分支：每个回答通向它自己的下一个对话框。视频对话框会在其他对话框之间播放你自己的影片（MP{n} 或 WebM）。",
    "Build the rooms of this map": "建造这张地图的房间",
    "Build the rooms of this side quest": "建造这个支线任务的房间",
    "Build the rooms ▸": "建造房间 ▸",
    "Campaign ▸": "战役 ▸",
    "City": "城市",
