    "City visit (plays the next time the party enters the city)": "城市拜访（下一次小队进入城市时播放）",
    "Comes after (arrows into it)": "位于之后（指向它的箭头）",
    "Crafting materials": "制作材料",
    "the bell hangs in its frame: a bell on the table takes the bell frame, and with one frame only one bell hangs at a time": "钟挂在钟架上：桌面上的钟需要钟架，一个钟架同一时间只能挂一口钟",
    "Del deletes": "Del 删除",
