    "Delete the campaign “{q}”?": "删除战役“{Q}”？",
    "Delete this map": "删除这张地图",
    "Delete this scene": "删除此场景",
    "Delete this side quest": "删除此支线任务",
    "Delete this waypoint": "删除此路径点",
    "Delete without exporting": "不导出直接删除",
    "Description (shown on the world map)": "描述（显示在世界地图上）",
    "Do not warn me again (⚙ Settings brings the warning back)": "不再警告我（在 ⚙ 设置中可恢复该警告）",
    "Drag a card to move it": "拖动卡片以移动它",
    "Drag a marker to place it on the world map": "拖动标示以把它放到世界地图上",
    "Erase the campaign, all its maps and its workshop from the editor": "从编辑器中擦除战役、其所有地图及其工坊",
    "Every map, side quest and waypoint has a place here and a marker kind: main quest, side quest, narrative event or city visit.": "每张地图、每个支线任务和路径点在这里都有一个位置和一种标示类型：主线任务、支线任务、叙述性事件或城市拜访。",
    "Everything of this campaign is erased from the editor, and it cannot be undone:": "此战役的所有内容都会从编辑器中擦除，且无法撤销：",
    "Export campaign": "导出战役",
    "Export, then delete": "先导出，再删除",
    "Files already exported stay in the folder": "已经导出的文件仍留在文件夹中",
    "Files already exported stay in the folder; delete them there if you want. Autosave stops following this campaign, so it will not erase them. The game keeps the progress of any party that played it.": "已经导出的文件仍留在文件夹中；如果你愿意，可以在那里删除它们。自动保存将不再跟随此战役，因此不会擦除它们。游戏会保留玩过它的任何小队的进度。",
    "Fit the whole flow in the view": "让整个流程适应视图",
    "Give crafting materials": "给予制作材料",
    "Give the campaign a name (campaign screen).": "给战役起个名字（战役界面）。",
    "Happens as": "发生方式",
    "It waits for the next visit to the city after the card before it": "它会等待它之前的卡片之后的下一次城市拜访",
    "Lay the cards out left to right": "从左到右排列卡片",
    "Leads to": "通向",
