    "Main quest": "主线任务",
    "Map picture": "地图图片",
    "Mark a map or waypoint as completed": "把一张地图或一个路径点标记为已完成",
    "Name of the campaign": "战役名称",
    "Narrative event": "叙述性事件",
    "Narrative event (a marker on the world map)": "叙述性事件（世界地图上的一个标示）",
    "Narrative event (plays at its point of the story)": "叙述性事件（在剧情中的对应时点播放）",
    "New variable (Spared the bandit, Sided with the rebels…)": "新变量（饶了强盗、站在叛军一边……）",
    "No remembered choice yet: in a question box, tick “{q}”.": "还没有被记住的选择：在问题对话框中勾选“{Q}”。",
    "On the world map as": "在世界地图上显示为",
    "PNG or JPG, {n}:{n} ({n}×{n} fits exactly). It covers the whole frame the game shows": "PNG 或 JPG，{n}:{n}（{n}×{n} 正好合适）。它会覆盖游戏显示的整个画框",
    "PNG or JPG, {n}:{n} ({n}×{n} fits exactly). It covers the whole frame the game shows; the game's water, burnt land, place names and roads are hidden. The mist covers a fixed region of the game's own map (the Mistlands).": "PNG 或 JPG，{n}:{n}（{n}×{n} 正好合适）。它会覆盖游戏显示的整个画框；游戏的水域、焦土、地名和道路会被隐藏。雾会覆盖游戏自身地图上的一个固定区域（迷雾之地）。",
    "Place this waypoint on the world map": "把此路径点放到世界地图上",
    "Plays as": "播放方式",
    "Point at a line to light its arrow. To see where a card leads, click its ●.": "指向一条线即可点亮它的箭头。要查看一张卡片通向哪里，请点击它的 ●。",
    "Remember a choice": "记住一个选择",
    "Remember this answer": "记住这个回答",
    "Remove this arrow": "移除此箭头",
    "Rename: every answer, card and map trigger that uses it follows": "重命名：所有使用它的回答、卡片和地图触发器都会随之更新",
    "Rewards on completion": "完成时的奖励",
    "Scene {n}": "场景 {n}",
