    "Side quest": "支线任务",
    "Side quest {n}": "支线任务 {n}",
    "Simulation": "模拟",
    "Stay and fill them": "留下并填写",
    "Story flow": "剧情流程",
    "The choices the campaign remembers from one map to the next: spared the bandit, sided with the rebels, took the cursed ring… A choice is set when the party picks an answer ticked “{q}” (or by a “{q}” action) and stays for the rest of the campaign. Cards of the story flow and triggers of the maps can then happen only if the party made it, or did not.": "战役从一张地图带到下一张地图的选择：饶了强盗、站在叛军一边、拿走了诅咒之戒……当小队选择一个勾选了“{Q}”的回答（或通过“{Q}”行动）时，选择就会被设定，并在战役剩余部分中保留。之后，剧情流程中的卡片和地图中的触发器可以设为仅在小队做出（或没有做出）该选择时才发生。",
    "The party moves on the world map (it goes after the selected card)": "小队在世界地图上移动（它会排在所选卡片之后）",
    "The scene goes on with the next box when the film ends.": "影片结束后，场景继续播放下一个对话框。",
    "Then:": "然后：",
    "They are exported as they are. Fill them, or delete the ones you do not need.": "它们会按原样导出。请填写它们，或删除你不需要的。",
    "Type the name of the campaign to confirm:": "输入战役名称以确认：",
    "Unlock a map or waypoint": "解锁一张地图或一个路径点",
    "Use my own city picture…": "使用我自己的城市图片……",
    "Use my own world map…": "使用我自己的世界地图……",
    "Used by": "使用者",
    "Video (your own film)": "视频（你自己的影片）",
    "Video {n}": "视频 {n}",
    "Waypoint {n}": "路径点 {n}",
    "What it means (a note for you)": "它的含义（给你自己的备注）",
    "When this box is shown": "显示此对话框时",
    "World map": "世界地图",
    "World map position: -{n}, {n}.": "世界地图位置：-{n}, {n}。",
    "World map position: {n}, {n}.": "世界地图位置：{n}, {n}。",
    "Write the boxes of this scene": "编写此场景的对话框",
    "Write the boxes ▸": "编写对话框 ▸",
    "Writes the .bcamp and its maps (download), then deletes.": "写出 .bcamp 及其地图（下载），然后删除。",
    "You are building the rooms of this map. Pick another map, or add maps, waypoints and dialogues, on the campaign screen (“{q}” above).": "你正在建造这张地图的房间。在战役界面（上方的“{Q}”）中选择另一张地图，或添加地图、路径点和对话。",
    "after Map {n}": "在地图 {n} 之后",
    "after Side quest {n}": "在支线任务 {n} 之后",
    "after Waypoint {n}": "在路径点 {n} 之后",
    "after a waypoint it plays on arrival": "在路径点之后，它在抵达时播放",
    "arrows nudge the selected card (or the view)": "方向键微调所选卡片（或视图）",
    "before anything it opens the campaign.": "在一切之前，它开启战役。",
    "campaign progression {n} (Map setup → Balancing).": "战役进度 {n}（地图设置 → 平衡）。",
    "double-click the background adds a box": "双击背景添加对话框",
    "drag from its ● onto another card to link (the target comes after)": "从它的 ● 拖到另一张卡片上进行连接（目标排在之后）",
    "end of the scene": "场景结束",
    "faded dots are the official destinations": "淡色圆点是官方目的地",
