    "map {n} of {n}": "地图 {n} / {n}",
    "narrator": "叙述者",
    "nothing depends on it yet: pick it in “{q}” of a card, or as the requirement “{q}” of a map trigger.": "还没有内容依赖于它：在一张卡片的“{Q}”中选择它，或作为地图触发器的要求“{Q}”。",
    "nothing sets it yet: tick “{q}” in a question box and give it this name. Until then “{q}” is never true.": "还没有内容设定它：在问题对话框中勾选“{Q}”并给它这个名字。在此之前，“{Q}”永远不会成立。",
    "only a question may branch": "只有问题可以产生分支",
    "progression {n}": "进度 {n}",
    "question": "问题",
    "the name is yours.": "名称由你决定。",
    "the scenes that follow it play in the same visit.": "紧随其后的场景在同一次拜访中播放。",
    "the story flow: {n} card(s), {n} scene(s) with their boxes, {n} story variable(s)": "剧情流程：{n} 张卡片、{n} 个场景及其对话框、{n} 个剧情变量",
    "the workshop: {n} monster(s), {n} NPC(s), {n} item(s), {n} hero(es), {n} weapon(s), {n} recipe(s), {n} feat(s), {n} tile(s)/object(s) of your own": "工坊：{n} 个怪物、{n} 个 NPC、{n} 件物品、{n} 位英雄、{n} 件武器、{n} 个配方、{n} 个功绩、{n} 个你自己的板块/物件",
    "the world map positions, the rewards, the music and videos chosen": "世界地图位置、奖励、所选的音乐和视频",
    "with your own map picture, draw the roads on the left": "使用你自己的地图图片时，在左侧绘制道路",
    "without a name": "未命名",
    "{n} box(es): text, questions and videos (your own films), played one after the other in the same frame. Played at this point of the story: after a map it is the map’s closing scene": "{n} 个对话框：文本、问题和视频（你自己的影片），在同一画框中依次播放。在剧情中的此时点播放：在地图之后，它是该地图的结束场景",
    "{n} box(es): text, questions and videos (your own films), played one after the other in the same frame. Played at this point of the story: after a map it is the map’s closing scene; after a waypoint it plays on arrival; before anything it opens the campaign.": "{n} 个对话框：文本、问题和视频（你自己的影片），在同一画框中依次播放。在剧情中的此时点播放：在地图之后，它是该地图的结束场景；在路径点之后，它在抵达时播放；在一切之前，它开启战役。",
