    "Original maps": "原版地图",
    "The original maps of the game are read by the Bigorna mod from your own copy of the game: start the game once with the mod installed (the title screen prepares them), then open the editor from the Editor folder of the game again.": "游戏的原版地图由 Bigorna 模组从你自己的游戏副本中读取：先在安装了模组的情况下启动一次游戏（标题界面会准备好它们），然后再从游戏的 Editor 文件夹中打开编辑器。",
    "The quests of the game, converted into maps of the editor: tiles, objects, rooms, monsters and the logic the triggers can say.": "游戏中的任务，已转换为编辑器的地图：板块、物件、房间、怪物以及触发器能够表达的逻辑。",
