    "How many of each piece you have: the generators use only these, and the object buttons show how many are on the table while a room is open. A blank field uses the estimate for your boxes (shown faded); ∞ means no limit. Two boxes, or a piece made by hand: raise the number.": "你拥有的每种部件有多少：生成器只使用这些，房间打开时物件按钮会显示桌面上有多少。留空的字段使用对你的盒子的估算值（淡色显示）；∞ 表示没有限制。有两个盒子，或手工制作了部件：请提高数字。",
