    "Program it here, then use “Save the default” at the top.": "在这里为它编程，然后使用顶部的“保存默认设置”。",
    "The texts and triggers of this object become its default, in the Workshop: objects placed from now on come with them": "此物件的文本和触发器将成为它在工坊中的默认设置：今后放置的物件都会带有它们",
    "The texts and triggers of this object become a new object of the Workshop (a copy of this piece of the game, with this default); you name it": "此物件的文本和触发器将成为工坊中的一个新物件（游戏中这个部件的副本，带有此默认设置）；由你为它命名",
