    "Add and change triggers": "添加和更改触发器",
    "No trigger yet.": "还没有触发器。",
    "“Add and change triggers” opens the piece alone on a board of its own, with the object panel of the map; your work waits aside until you save or cancel. Copies placed with “Default script” ticked come with this default.": "“添加和更改触发器”会把这个部件单独放在它自己的版图上打开，并带有地图的物件面板；在你保存或取消之前，你的作品会暂放一旁。勾选“默认脚本”放置的副本会带有此默认设置。",
    "now in": "现在属于",
    "Who plays the profile of": "谁扮演以下英雄的档案：",
