    "Objects of the game": "游戏的物件",
    "The game’s tiles, as they are. Duplicate one to make a Workshop tile of the same shape.": "游戏的板块，保持原样。复制一个即可制作相同形状的工坊板块。",
    "This object has no default in the game.": "此物件在游戏中没有默认设置。",
    "An object of the game: it is changed nowhere. “Duplicate” makes a copy: on the board and in the game it is this same piece, but it has a default of its own, starting from this one. Make as many copies as you like, each with a different default; they wait in the Object palette, under the Workshop’s.": "游戏中的物件：它在任何地方都不会改变。“复制”会制作一个副本：在版图上和游戏中它是同一个部件，但拥有自己的默认设置，以此物件的为起点。你可以做任意多个副本，每个都有不同的默认设置；它们会在“物件”调色板中工坊物件的下方等待。",
    "Duplicated: the copy has its own default, to change at will.": "已复制：副本拥有自己的默认设置，可以随意修改。",
    "On the board and in the game it is the game’s piece": "在版图上和游戏中，它是游戏的部件",
    "What changes is its default.": "改变的是它的默认设置。",
    "To change the triggers: put this copy on the map (it is in the Object palette), program it and use “Save as the default” in its panel: the default comes back to this copy. Copies placed with “Default script” ticked come with it.": "要更改触发器：把这个副本放到地图上（它在“物件”调色板中），为它编程，然后在它的面板中使用“另存为默认”：默认设置就会回到这个副本。勾选“默认脚本”放置的副本会带有它。",
    "Replace the default of this copy with the game’s?": "用游戏的默认设置替换此副本的默认设置？",
    "The six heroes side by side; change any of them for a hero of the roster": "六位英雄并排显示；可以把其中任何一位换成名册中的英雄",
    "The party of the campaign": "战役的小队",
