    "hero of the roster": "位名册英雄",
    "The six heroes the players choose from. Each one can be changed for a hero of the roster, who takes the class, the two weapons, the skills and the feats of that profile. Click a figure to open its sheet.": "玩家可以选择的六位英雄。每一位都可以换成名册中的英雄，该英雄会获得那个档案的职业、两件武器、技能和功绩。点击一个模型即可打开它的表格。",
    "Open the sheet": "打开表格",
