    "Now it is yours: the changes go into your Workshop.": "现在它属于你了：更改会写入你的工坊。",
    "In the Bigorna Editor app, exported files go straight into the game's <b>Bigorna\\Mapas</b> folder, and the Workshop is kept in the <b>Pacotes</b> folder, next to it.": "在 Bigorna Editor 应用中，导出的文件会直接存入游戏的 <b>Bigorna\\Mapas</b> 文件夹，而工坊保存在它旁边的 <b>Pacotes</b> 文件夹中。",
